CREATE OR REPLACE TABLE `driiiportfolio.analytics.fact_enrollment` AS SELECT ROW_NUMBER() OVER() as enrollment_key, s.student_key, e.course_id, e.grade, e.grade_point, e.year as academic_year FROM `driiiportfolio.staging.enrollments` e JOIN `driiiportfolio.analytics.dim_student` s ON e.student_id = s.student_id;
CREATE OR REPLACE TABLE `driiiportfolio.analytics.fact_research_grant` AS SELECT ROW_NUMBER() OVER() as grant_key, g.grant_id, f.faculty_key as pi_key, g.award_amount, g.status as current_status, g.publication_count FROM `driiiportfolio.staging.grants` g JOIN `driiiportfolio.analytics.dim_faculty` f ON g.pi_id = f.faculty_id;
